:root { font-family: system-ui, sans-serif; color: #18212f; background: #f5f7fa; }
body { margin: 0; }
.layout { max-width: 760px; margin: 4rem auto; padding: 2rem; background: white; border-radius: 12px; box-shadow: 0 8px 30px #17233a12; }
h1 { margin-top: 0; }
form { display: grid; grid-template-columns: 1fr auto; gap: .6rem 1rem; align-items: center; }
form label { grid-column: 1 / -1; font-weight: 600; }
input, button { font: inherit; padding: .65rem .85rem; border: 1px solid #aab4c2; border-radius: 6px; }
button { cursor: pointer; background: #174ea6; border-color: #174ea6; color: white; }
button:hover { background: #103d85; }
[role="alert"] { color: #a12622; }
article[data-testid="project-row"] { display: flex; align-items: center; justify-content: space-between; gap: 1rem; border-top: 1px solid #d9dfe8; padding: 1rem 0; }
section[aria-label="Projects"] { margin-top: 1.5rem; }
